fn solve(input: Vec<char>) -> Vec<char> {
    // According to the problem statement, the input is guaranteed to be of the form:
    // "AtCoder <Name> Contest\n"
    // where <Name> is nonempty, starts with an uppercase letter, and is followed by lowercase letters.
    //
    // The first character of <Name> is at index 8, because:
    // "AtCoder" → 7 chars (indices 0..6)
    // " "       → 1 char  (index 7)
    // so the name starts at index 8.
    let initial = input[8];
    build_result(initial)
}

fn build_result(ch: char) -> Vec<char> {
    // Build the 4-character output: 'A', <initial>, 'C', '\n'
    vec!['A', ch, 'C', '\n']
}

